import React, { useState, useEffect } from 'react';
import { ShoppingListItem } from '../types';
import { TrashIcon } from './icons/TrashIcon';

interface ItemRowProps {
    item: ShoppingListItem;
    onUpdateItem: (id: string, newQuantity: number) => void;
    onDeleteItem: (id: string) => void;
}

const formatCurrency = (value: number) => {
    return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

export const ItemRow: React.FC<ItemRowProps> = ({ item, onUpdateItem, onDeleteItem }) => {
    // Estado local para permitir digitação livre sem formatação forçada a cada tecla
    const [inputValue, setInputValue] = useState(item.quantity.toString());
    const [isFocused, setIsFocused] = useState(false);

    // Sincroniza o estado local com a prop item.quantity quando o item muda externamente
    // Mas APENAS se o usuário não estiver editando o campo neste momento
    useEffect(() => {
        if (!isFocused) {
            // Formata para remover zeros desnecessários (ex: 1.50 vira 1.5) mas mantém precisão se necessário
            setInputValue(parseFloat(item.quantity.toFixed(2)).toString());
        }
    }, [item.quantity, isFocused]);

    const handleQuantityChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const newValue = e.target.value;
        setInputValue(newValue);

        const parsed = parseFloat(newValue);
        if (!isNaN(parsed)) {
            onUpdateItem(item.id, parsed);
        } else if (newValue === '') {
            // Opcional: permitir que fique vazio visualmente, mas tratar como 0 ou manter último valor válido no estado global
             onUpdateItem(item.id, 0);
        }
    };

    const handleBlur = () => {
        setIsFocused(false);
        // Ao sair do campo, garante a formatação limpa
        setInputValue(parseFloat(item.quantity.toFixed(2)).toString());
    };

    const handleFocus = () => {
        setIsFocused(true);
    };

    const totalItem = item.quantity * item.price;

    return (
        <tr className="hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors duration-150">
            <td className="px-4 py-2 whitespace-nowrap">
                <div className="text-sm font-medium text-gray-900 dark:text-gray-100">{item.name}</div>
                <div className="text-xs text-gray-500 dark:text-gray-400">{item.unit}</div>
            </td>
            <td className="px-4 py-2 whitespace-nowrap">
                <input
                    type="number"
                    value={inputValue}
                    onChange={handleQuantityChange}
                    onFocus={handleFocus}
                    onBlur={handleBlur}
                    onWheel={(e) => e.currentTarget.blur()}
                    className="w-24 p-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                    step="0.01"
                    min="0"
                />
            </td>
            <td className="px-4 py-2 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">{formatCurrency(item.price)}</td>
            <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-gray-800 dark:text-gray-200">{formatCurrency(totalItem)}</td>
            <td className="px-1 py-2 whitespace-nowrap text-center">
                <button
                    onClick={() => onDeleteItem(item.id)}
                    className="text-red-500 hover:text-red-700 p-2 rounded-full hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors"
                    aria-label={`Remover ${item.name}`}
                >
                    <TrashIcon />
                </button>
            </td>
        </tr>
    );
};

import { ShoppingListItem } from '../types';

declare global {
    interface Window {
        jspdf: any;
    }
}

const formatCurrency = (value: number) => {
    return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

const getFilename = (userFileName: string | undefined, extension: string) => {
    const timestamp = new Date().toISOString().slice(0, 19).replace(/[-:T]/g, '');
    let name = userFileName && userFileName.trim() !== '' ? userFileName.trim() : `Lista_de_Compras_${timestamp}`;

    // Ensure extension is correct
    if (!name.toLowerCase().endsWith(`.${extension}`)) {
        name = `${name}.${extension}`;
    }
    return name;
};

export const generateCsv = (items: ShoppingListItem[], fileName?: string) => {
    if (items.length === 0) return;

    let csvContent = "PRODUTOS;QUANTIDADE;UNIDADE;PREÇO P/ UNID.;VALOR TOTAL\n";
    let totalGeral = 0;

    items.forEach(item => {
        if (item.quantity > 0) {
            const totalItem = item.quantity * item.price;
            totalGeral += totalItem;

            const qtdFormatada = item.quantity.toFixed(2).replace('.', ',');
            const precoFormatado = `R$ ${item.price.toFixed(2)}`.replace('.', ',');
            const totalFormatado = `R$ ${totalItem.toFixed(2)}`.replace('.', ',');

            csvContent += `${item.name};${qtdFormatada};${item.unit};${precoFormatado};${totalFormatado}\n`;
        }
    });

    const totalGeralFinalFormatado = `R$ ${totalGeral.toFixed(2)}`.replace('.', ',');
    csvContent += `;;;TOTAL GERAL;${totalGeralFinalFormatado}\n`;

    const blob = new Blob([`\uFEFF${csvContent}`], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    const downloadName = getFilename(fileName, 'csv');

    link.setAttribute("href", url);
    link.setAttribute("download", downloadName);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const generatePdf = (items: ShoppingListItem[], fileName?: string) => {
    if (items.length === 0) return;

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    const tableColumns = ['Produto', 'Qtd', 'Unid', 'Preço Unit.', 'Valor Total'];
    const tableRows: (string | number)[][] = [];
    let totalGeral = 0;

    items.forEach(item => {
        if (item.quantity > 0) {
            const totalItem = item.quantity * item.price;
            totalGeral += totalItem;

            tableRows.push([
                item.name,
                item.quantity.toFixed(2),
                item.unit,
                formatCurrency(item.price),
                formatCurrency(totalItem)
            ]);
        }
    });

    doc.autoTable({
        head: [tableColumns],
        body: tableRows,
        startY: 20,
        theme: 'striped',
        headStyles: { fillColor: [30, 64, 175] } // Tailwind's blue-700
    });

    const finalY = (doc as any).lastAutoTable.finalY;
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text(`TOTAL GERAL ESTIMADO: ${formatCurrency(totalGeral)}`, 14, finalY + 15);

    const downloadName = getFilename(fileName, 'pdf');
    doc.save(downloadName);
};

